  ''platform_private.claim_subscription_fiscal_operation(uuid)'',
  ''platform_private.record_subscription_fiscal_result(uuid,uuid,text,text,bigint,text,uuid,text,text)'',
  ''platform_private.check_linked_fiscal_refund_send(uuid,jsonb)'',
  ''platform_private.record_linked_subscription_fiscal_refund(uuid,jsonb)'',
  ''platform_private.begin_recurring_attempt(uuid)'',
  ''platform_private.authorize_recurring_send(uuid,uuid)'',
  ''platform_private.claim_recurring_dispatch(uuid,uuid)'',
  ''platform_private.record_recurring_result(uuid,jsonb)'',
  ''platform_private.apply_recurring_period(uuid)'',
  ''platform_private.fulfill_discount_payment(uuid)'',
  ''platform_private.fulfill_zero_discount_checkout(uuid)'',
  ''platform_private.run_scheduled_sandbox_orders()'',
  ''platform_private.run_scheduled_subscription_settlements()'',
  ''public.retry_sandbox_subscription_refund_application(text,uuid)'',
  ''platform_private.apply_subscription_refund(uuid)'',
  ''platform_private.apply_current_subscription_refund(uuid)'',
  ''platform_private.apply_future_trial_subscription_refund(uuid)'',
  ''platform_private.schedule_confirmed_period_after_trial(uuid)'',
  ''platform_private.confirm_trial_checkout_replacement(uuid)'',
  ''platform_private.defer_future_discount_payment(uuid)''
 ] loop
  definition:=pg_get_functiondef(signature::regprocedure);
  select prosrc into source from pg_proc where oid=signature::regprocedure
   and prolang=(select oid from pg_language where lanname=''plpgsql'');
  if source is null then raise exception ''sandbox guard requires plpgsql: %'',signature; end if;
  prefix:=substring(source from E''(?is)^(.*?)\\mbegin\\M'');
  -- Reject ambiguous comment/inline markers instead of silently patching them.
  -- This is a structural check for the reviewed historical bodies, not a parser.
  if prefix is null or prefix !~ E''(^|\n)[ \t]*$'' then
   raise exception ''sandbox guard entry marker ambiguous: %'',signature;
  end if;
  patched:=regexp_replace(source,E''\\mbegin\\M'',
   E''begin\n perform platform_private.require_sandbox_environment();'',''i'');
  if patched=source then raise exception ''sandbox guard entry marker missing: %'',signature; end if;
  if (length(definition)-length(replace(definition,source,'''')))/length(source)<>1 then
   raise exception ''sandbox guard source occurrence ambiguous: %'',signature;
  end if;
  execute replace(definition,source,patched);
 end loop;
end;
$$;
-- STABLE entitlement projection cannot acquire row locks. Deny only the branch
-- deriving paid access from a sandbox purchase; ordinary trial remains usable.
create function platform_private.require_sandbox_projection() returns void
language plpgsql stable security definer set search_path='''' as $$
begin
 if not exists(select 1 from platform_private.billing_runtime_environment
  where singleton and environment=''sandbox'') then
  raise exception ''sandbox environment denied'' using errcode=''42501'';
 end if;
end; $$;
revoke all on function platform_private.require_sandbox_projection() from public,anon,authenticated,service_role;
do $$
declare definition text; marker text;
begin
 definition:=pg_get_functiondef(''public.effective_trial_subscription(public.organization_subscriptions,timestamptz)''::regprocedure);
 marker:=''if found and p_at>=paid.period_start then'';
 if (length(definition)-length(replace(definition,marker,'''')))/length(marker)<>1 then raise exception ''paid projection guard marker missing or ambiguous''; end if;
 execute replace(definition,marker,marker||'' perform platform_private.require_sandbox_projection();'');
 definition:=pg_get_functiondef(''public.advance_organization_trial(uuid)''::regprocedure);
 marker:=''select * into s from public.organization_subscriptions where organization_id=p_organization_id for update;'';
 if (length(definition)-length(replace(definition,marker,'''')))/length(marker)<>1 then raise exception ''trial runner guard marker missing or ambiguous''; end if;
 execute replace(definition,marker,
  ''if exists(select 1 from platform_private.active_trial_paid_periods where organization_id=p_organization_id) then
   perform platform_private.require_sandbox_environment(); end if; ''||marker);
end; $$;

-- Reauthorization of a persisted HTTP request must recheck the environment.
-- Poll/review stay available; claim/record already cross their guarded primitives.
do $worker_guard$
declare definition text; source text; marker text:=E''begin\n if current_setting(''''transaction_isolation'''')'';
begin
 definition:=pg_get_functiondef(''public.subscription_fiscal_worker_gateway(text,text,uuid,uuid,jsonb)''::regprocedure);
 select replace(prosrc,E''\r\n'',E''\n'') into source from pg_proc
 where oid=''public.subscription_fiscal_worker_gateway(text,text,uuid,uuid,jsonb)''::regprocedure;
 if (length(source)-length(replace(source,marker,'''')))/length(marker)<>1 then
  raise exception ''fiscal worker entry marker missing or ambiguous''; end if;
 execute replace(replace(definition,E''\r\n'',E''\n''),source,
  replace(source,marker,E''begin\n if p_action=''''before_send'''' then perform platform_private.require_sandbox_environment(); end if;\n if current_setting(''''transaction_isolation'''')''));
end; $worker_guard$;


-- Recovery may authorize another POST without a new claim. Keep identified GET recovery available.
do $recovery_guard$
declare definition text; source text; marker text:=E''begin\n perform public.require_platform_owner();'';
begin
 definition:=pg_get_functiondef(''platform_private.prepare_subscription_refund_recovery(uuid)''::regprocedure);
 select replace(prosrc,E''\r\n'',E''\n'') into source from pg_proc
 where oid=''platform_private.prepare_subscription_refund_recovery(uuid)''::regprocedure;
 if (length(source)-length(replace(source,marker,'''')))/length(marker)<>1 then
  raise exception ''refund recovery entry marker missing or ambiguous''; end if;
 execute replace(replace(definition,E''\r\n'',E''\n''),source,replace(source,marker,marker||E''\n if not exists(select 1 from public.billing_sandbox_refunds where id=p_refund_id and provider_refund_id is not null) then\n  perform platform_private.require_sandbox_environment();\n end if;''));
end; $recovery_guard$;


-- Apply after the environment guard, before one-time environment provisioning.
-- Environment identity is not a sales switch. Historical environment transitions
-- require a separately reviewed data migration, not an UPDATE to this singleton.

create function platform_private.check_initial_billing_environment() returns trigger
language plpgsql security definer set search_path='''' as $$
declare relation_name text; populated boolean;
begin
 if new.environment<>''production'' then return new; end if;
 -- Explicit conservative inventory: reject operational history, not catalog or
 -- organization rows. Lock each source against concurrent provisioning.
 for relation_name in
  select c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace
  where n.nspname=''public'' and c.relkind=''r'' and (
   c.relname like ''billing_sandbox_%'' or c.relname like ''billing_recurring_%''
   or c.relname in (''billing_discount_checkouts'',''billing_trial_paid_periods'',
    ''billing_fiscal_acceptance_fixtures'',''billing_receipt_snapshots'',
    ''billing_subscription_fiscal_operations'',''billing_period_confirmations'',
    ''billing_confirmation_inbox'',''billing_review_resolutions''))
  order by c.relname
 loop
  execute format(''lock table public.%I in share mode'',relation_name);
  execute format(''select exists(select 1 from public.%I)'',relation_name) into populated;
  if populated then raise exception ''production environment requires clean billing history: %'',relation_name using errcode=''55000''; end if;
 end loop;
 lock table public.billing_fiscal_policies in share mode;
 if exists(select 1 from public.billing_fiscal_policies where environment=''sandbox'') then
  raise exception ''production environment requires clean fiscal policies'' using errcode=''55000'';
 end if;
 return new;
end; $$;
revoke all on function platform_private.check_initial_billing_environment() from public,anon,authenticated,service_role;
create trigger billing_environment_initial_check before insert on platform_private.billing_runtime_environment
 for each row execute function platform_private.check_initial_billing_environment();
create function platform_private.protect_billing_environment_identity() returns trigger
language plpgsql set search_path='''' as $$
begin
 if tg_op=''UPDATE'' and new is not distinct from old then return new; end if;
 raise exception ''billing environment identity immutable'' using errcode=''55000'';
end; $$;
revoke all on function platform_private.protect_billing_environment_identity() from public,anon,authenticated,service_role;
create trigger billing_environment_identity_immutable
 before update or delete on platform_private.billing_runtime_environment
 for each row execute function platform_private.protect_billing_environment_identity();
create trigger billing_environment_identity_no_truncate
 before truncate on platform_private.billing_runtime_environment
 for each statement execute function platform_private.protect_billing_environment_identity();
';
 else
  lock table platform_private.billing_runtime_environment in access exclusive mode;
 end if;
 select catalog into actual from (with targets as (select unnest(array['platform_private.prepare_subscription_refund_recovery(uuid)','public.subscription_fiscal_worker_gateway(text,text,uuid,uuid,jsonb)','public.begin_sandbox_refund(uuid)','public.advance_organization_trial(uuid)','public.begin_sandbox_payment_send(uuid)','public.claim_prepayment_settlement(uuid)','public.record_sandbox_refund(uuid,uuid,text)','platform_private.apply_recurring_period(uuid)','platform_private.begin_recurring_attempt(uuid)','public.apply_sandbox_payment_event(uuid,jsonb)','platform_private.fulfill_discount_payment(uuid)','platform_private.run_scheduled_sandbox_orders()','public.reserve_sandbox_refund(uuid,uuid,bigint)','platform_private.apply_subscription_refund(uuid)','public.prepare_fiscal_acceptance_fixture(uuid,text)','public.record_prepayment_settlement(uuid,text,text)','platform_private.authorize_recurring_send(uuid,uuid)','platform_private.claim_recurring_dispatch(uuid,uuid)','platform_private.defer_future_discount_payment(uuid)','platform_private.record_recurring_result(uuid,jsonb)','platform_private.fulfill_zero_discount_checkout(uuid)','platform_private.apply_current_subscription_refund(uuid)','platform_private.claim_subscription_refund_dispatch(uuid)','platform_private.confirm_trial_checkout_replacement(uuid)','platform_private.run_scheduled_subscription_settlements()','platform_private.claim_subscription_fiscal_operation(uuid)','platform_private.check_linked_fiscal_refund_send(uuid,jsonb)','platform_private.schedule_confirmed_period_after_trial(uuid)','platform_private.apply_future_trial_subscription_refund(uuid)','public.retry_sandbox_subscription_refund_application(text,uuid)','platform_private.record_linked_subscription_fiscal_refund(uuid,jsonb)','public.record_sandbox_payment_result(uuid,uuid,text,boolean,boolean,text)','public.effective_trial_subscription(public.organization_subscriptions,timestamptz)','platform_private.reserve_subscription_fiscal_operation(uuid,uuid,bigint,text,bigint)','platform_private.record_subscription_fiscal_result(uuid,uuid,text,text,bigint,text,uuid,text,text)','public.reserve_sandbox_payment_order(uuid,uuid,bigint,uuid,bigint,text,text,timestamptz,timestamptz)','platform_private.require_sandbox_environment()','platform_private.require_sandbox_projection()','platform_private.guard_sandbox_period_confirmation()','platform_private.check_initial_billing_environment()','platform_private.protect_billing_environment_identity()']) as signature),
 funcs as (
 select t.signature,replace(pg_get_functiondef(p.oid),chr(13)||chr(10),chr(10)) as definition,
  pg_get_userbyid(p.proowner) as owner,
  coalesce((select jsonb_agg(jsonb_build_array(coalesce(r.rolname,'PUBLIC'),a.privilege_type,a.is_grantable) order by coalesce(r.rolname,'PUBLIC'),a.privilege_type,a.is_grantable)
   from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a left join pg_roles r on r.oid=a.grantee),'[]'::jsonb) as acl
 from targets t left join pg_proc p on p.oid=to_regprocedure(t.signature)
 ),
 relation as (
 select c.relkind,c.relpersistence,c.relrowsecurity,c.relforcerowsecurity,pg_get_userbyid(c.relowner) as owner,
  coalesce((select jsonb_agg(jsonb_build_array(coalesce(r.rolname,'PUBLIC'),a.privilege_type,a.is_grantable) order by coalesce(r.rolname,'PUBLIC'),a.privilege_type,a.is_grantable)
   from aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a left join pg_roles r on r.oid=a.grantee),'[]'::jsonb) as acl
 from pg_class c where c.oid=to_regclass('platform_private.billing_runtime_environment')
 ),
 columns as (
 select a.attname,format_type(a.atttypid,a.atttypmod) as type,a.attnotnull,a.attidentity,a.attgenerated,
 pg_get_expr(d.adbin,d.adrelid) as default_expression,a.attacl::text
 from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum
 where a.attrelid=to_regclass('platform_private.billing_runtime_environment') and a.attnum>0 and not a.attisdropped
 ),
 constraints as (
 select conname,contype,convalidated,pg_get_constraintdef(oid) as definition
 from pg_constraint where conrelid=to_regclass('platform_private.billing_runtime_environment')
 ),
 triggers as (
 select n.nspname||'.'||c.relname as relation,t.tgname,t.tgenabled,pg_get_triggerdef(t.oid) as definition
 from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace
 where not t.tgisinternal and (t.tgrelid=to_regclass('platform_private.billing_runtime_environment')
 or (t.tgrelid='public.billing_period_confirmations'::regclass and t.tgname='sandbox_period_confirmation_environment'))
 ),
 policies as (
 select polname,polcmd,polpermissive,polroles::text,pg_get_expr(polqual,polrelid) as qual,pg_get_expr(polwithcheck,polrelid) as check_expr
 from pg_policy where polrelid=to_regclass('platform_private.billing_runtime_environment')
 )
 select jsonb_build_object(
 'functions',(select jsonb_agg(to_jsonb(f) order by signature) from funcs f),
 'relation',(select to_jsonb(r) from relation r),
 'columns',(select jsonb_agg(to_jsonb(a) order by attname) from columns a),
 'constraints',(select jsonb_agg(to_jsonb(c) order by conname) from constraints c),
 'triggers',(select jsonb_agg(to_jsonb(t) order by relation,tgname) from triggers t),
 'policies',(select coalesce(jsonb_agg(to_jsonb(p) order by polname),'[]'::jsonb) from policies p)
 ) as catalog) snapshot;
 if actual is distinct from expected then
  raise exception 'billing guard catalog mismatch';
 end if;
end; $adopt$;
commit;
